use std::collections::BTreeSet;
use std::io::BufRead;


use rig::completion::CompletionRequest;
use rig::message::{ToolResultContent, UserContent};
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};
use rig::run::{AgentRun, AgentRunStep, ModelTurn, ModelTurnOutcome};
use rig::run::InvalidToolCallAction;
use rig::tool::ToolSet;


const PREAMBLE: &str = "You are a banking assistant. Use the tools to carry out the request.";


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let model = OpenAI::from_env()?.completion(openai::GPT_5_5);
    let mut tools = ToolSet::default();
    tools.add_tool(TransferFunds);
    let definitions = tools.tool_definitions();
    let tool_names: BTreeSet<String> = definitions.iter().map(|d| d.name.to_string()).collect();
    let checkpoint = std::path::Path::new("run.json");


    let mut run = AgentRun::new("Transfer $500 to account B-2.").max_turns(4);


    loop {
        match run.next_step()? {
            AgentRunStep::CallModel { prompt, history, .. } => {
                let response = model
                    .call(
                        CompletionRequest::new(prompt)
                            .messages(history)
                            .preamble(PREAMBLE.to_string())
                            .tools(definitions.clone()),
                    )
                    .await?;
                let turn =
                    ModelTurn::from_response_parts(&response, tool_names.clone(), tool_names.clone());
                let mut outcome = run.model_response(turn)?;
                while let ModelTurnOutcome::NeedsResolution(_) = outcome {
                    outcome = run.resolve_invalid_tool_call(InvalidToolCallAction::fail())?;
                }
            }


            AgentRunStep::CallTools { .. } => {
                // Pause: persist the whole run while its tool calls wait for a decision.
                std::fs::write(checkpoint, serde_json::to_vec(&run)?)?;


                // ...later, possibly in another process: load it and get the calls back.
                let mut resumed: AgentRun = serde_json::from_slice(&std::fs::read(checkpoint)?)?;
                let AgentRunStep::CallTools { calls } = resumed.next_step()? else {
                    anyhow::bail!("a resumed run re-emits its pending tool calls");
                };


                let mut results = Vec::new();
                for call in calls {
                    // Calls already answered by invalid-call recovery must not run.
                    if let Some(result) = call.preresolved_result {
                        results.push(result);
                        continue;
                    }
                    let id = call.tool_call.id.clone();
                    let name = call.tool_call.function.name.clone();
                    let args = call.tool_call.function.arguments_value().to_string();


                    println!("approve {name}({args})? [y/N]");
                    let mut answer = String::new();
                    std::io::stdin().lock().read_line(&mut answer)?;


                    let content = if answer.trim() == "y" {
                        let result = tools.execute(&name, args, &mut ToolContext::new()).await;
                        result.output().clone().into_content()
                    } else {
                        // Fail-closed: anything but an explicit yes is a denial the model sees.
                        vec![ToolResultContent::text("denied by the reviewer")]
                    };
                    results.push(UserContent::tool_result(id, name, content));
                }
                resumed.tool_results(results)?;
                run = resumed;
            }


            AgentRunStep::Done(response) => {
                println!("{}", response.output());
                return Ok(());
            }
        }
    }
}

